def generate_candidates(
    ell: int, m: int
) -> list[tuple[list[tuple[int, int]], list[tuple[int, int]]]]:
    """Generate candidate (A_terms, B_terms) pairs for given lattice dimensions."""
    candidates = []
    seen = set()

    def _add(a_terms, b_terms):
        """Add candidate if not a duplicate."""
        key = (tuple(sorted(a_terms)), tuple(sorted(b_terms)))
        if key not in seen:
            seen.add(key)
            candidates.append((list(a_terms), list(b_terms)))

    # -----------------------------------------------------------------------
    # Helper: Identify "interesting" exponents
    # -----------------------------------------------------------------------
    def get_interesting_exponents(dim):
        """Returns small integers and factors of dim, useful for algebraic structure."""
        # Always check small integers
        exps = set(range(1, min(dim, 8)))
        # Check factors and multiples of factors
        for k in range(2, int(dim**0.5) + 2):
            if dim % k == 0:
                divs = [k, dim // k]
                for d in divs:
                    exps.add(d)
                    if 2 * d < dim: exps.add(2 * d)
                    if 3 * d < dim: exps.add(3 * d)
        # Add dim/2, dim/3 explicitly if integer
        if dim % 2 == 0: exps.add(dim // 2)
        if dim % 3 == 0: exps.add(dim // 3)
        return sorted([e for e in exps if 0 < e < dim])

    x_exps = get_interesting_exponents(ell)
    y_exps = get_interesting_exponents(m)

    # -----------------------------------------------------------------------
    # Strategy 1: Symmetric x/y-swap with structural patterns
    # Pattern: A = x^a + y^b + y^c, B = y^d + x^e + x^f
    # -----------------------------------------------------------------------

    # 1a. The "Doubling/Tripling" Pattern (classic BB codes)
    # A = x^a + y^b + y^(k*b), B = y^d + x^e + x^(k*e)
    # We iterate a, d from interesting sets. b, e from interesting sets.
    for k_mul in [2, 3]: # Try doubling and tripling
        for a in x_exps:
            for b in y_exps:
                c = (k_mul * b) % m
                if c == b or c == 0: continue

                A = [(a, 0), (0, b), (0, c)]

                for d in y_exps:
                    for e in x_exps:
                        f = (k_mul * e) % ell
                        if f == e or f == 0: continue

                        B = [(0, d), (e, 0), (f, 0)]
                        _add(A, B)

    # 1b. The "Unit-Offset" Pattern (found in best codes)
    # A = x^a + 1 + y^c  (effectively b=0)
    # B = y^d + 1 + x^f
    # This structure is highly effective for high-k.
    for a in x_exps:
        for c in y_exps:
            A = [(a, 0), (0, 0), (0, c)]

            for d in y_exps:
                for f in x_exps:
                    B = [(0, d), (0, 0), (f, 0)]
                    _add(A, B)

    # -----------------------------------------------------------------------
    # Strategy 2: Constant-Monomial Codes (A=f(y), B=g(x))
    # Pattern: A = 1 + y^a + y^b, B = 1 + x^c + x^d
    # -----------------------------------------------------------------------
    # We construct all valid 3-term polynomials from the interesting sets
    y_polys = []
    for i in range(len(y_exps)):
        for j in range(i + 1, len(y_exps)):
            y_polys.append([(0, 0), (0, y_exps[i]), (0, y_exps[j])])

    x_polys = []
    for i in range(len(x_exps)):
        for j in range(i + 1, len(x_exps)):
            x_polys.append([(0, 0), (x_exps[i], 0), (x_exps[j], 0)])

    # Evaluate cross product
    # Limit the number of candidates if sets are large (unlikely given construction)
    for A in y_polys:
        for B in x_polys:
            _add(A, B)

    # -----------------------------------------------------------------------
    # Strategy 3: Perturbations of Known Good Codes
    # -----------------------------------------------------------------------
    for code_spec in KNOWN_CODES:
        if code_spec["ell"] == ell and code_spec["m"] == m:
            base_A = code_spec["A_terms"]
            base_B = code_spec["B_terms"]
            _add(base_A, base_B)

            # Perturb exponents slightly
            for delta in [-1, 1]:
                for i in range(3):
                    # Perturb A
                    if base_A[i] != (0,0):
                        new_A = list(base_A)
                        val = new_A[i]
                        # adjust non-zero coord
                        if val[0] > 0: new_A[i] = ((val[0]+delta)%ell, 0)
                        else:          new_A[i] = (0, (val[1]+delta)%m)
                        if len(set(new_A)) == 3: _add(new_A, base_B)

                    # Perturb B
                    if base_B[i] != (0,0):
                        new_B = list(base_B)
                        val = new_B[i]
                        if val[0] > 0: new_B[i] = ((val[0]+delta)%ell, 0)
                        else:          new_B[i] = (0, (val[1]+delta)%m)
                        if len(set(new_B)) == 3: _add(base_A, new_B)

    return candidates
